imeZone=UTC"],"result":"jsonb","strict":false,"definer":true,"defaults":"24, NULL::jsonb","language":"plpgsql","parallel":"u","arguments":["p_seller_slug","p_result_limit","p_cursor"],"leakproof":false,"signature":"public.get_public_profile_jobs_v1(text,integer,jsonb)","volatility":"s"}]}'::jsonb before_t,'{"functions":[{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"body":"a4835de45c9ded23d2714f62641f04e3acb1b572346732c26ad00be5c97b4e5c","owner":"postgres","config":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"result":"boolean","strict":false,"definer":true,"defaults":null,"language":"sql","parallel":"u","arguments":["p_identity"],"leakproof":false,"signature":"jobs_private.visible_to_viewer(uuid)","volatility":"s"},{"acl":[{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"body":"0f3e3433296782c524927af67dd066704f2b8c49c226dcb2150aa24c3ec8d386","owner":"postgres","config":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"result":"jsonb","strict":false,"definer":true,"defaults":"24, NULL::jsonb","language":"plpgsql","parallel":"u","arguments":["p_seller_slug","p_result_limit","p_cursor"],"leakproof":false,"signature":"public.get_public_profile_jobs_v1(text,integer,jsonb)","volatility":"s"}]}'::jsonb after_t
), evaluated AS (
 SELECT base.value b,target.value t,CASE WHEN base.value=expected.b AND target.value=expected.before_t THEN 'before'
 WHEN base.value=expected.b AND target.value=expected.after_t THEN 'after' ELSE 'unknown' END state
 FROM base CROSS JOIN target CROSS JOIN expected
)
SELECT jsonb_build_object('format','selqiro-account-job-read-fence-20261124-v1','stage','preflight','state',state,
 'recognized',state IN ('before','after'),'read_only',true,
 'account_rows_read',false,'account_rows_exported',false,
 'base_fingerprint',encode(sha256(convert_to(b::text,'UTF8')),'hex'),
 'target_fingerprint',encode(sha256(convert_to(t::text,'UTF8')),'hex'),
 'fence_verified',state='after') INTO observed FROM evaluated;
 IF observed->>'state' IS DISTINCT FROM 'after' THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCOUNT_JOB_READ_SCHEMA_MISMATCH';
 END IF;
END;
