  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname IN ('service_publication_private.visible_to_viewer','public.get_public_profile_services_v1','public.get_public_profile_services_v2','service_publication_private.public_fields','public.get_public_service_v1','public.search_public_services_v1') ORDER BY n.nspname,p.proname,p.oid LIMIT 7) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
)
, service_columns AS (
 SELECT jsonb_agg(jsonb_build_object('relation',w.relation,'name',w.name,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text) ORDER BY w.relation COLLATE "C",w.name COLLATE "C") value
 FROM (VALUES ('public.identities','display_name'),('public.services','created_at'),('public.services','updated_at'),('public.services','published_at'),('public.services','sort_order'),('public.services','edit_revision')) w(relation,name) JOIN pg_attribute a ON a.attrelid=to_regclass(w.relation) AND a.attname=w.name AND NOT a.attisdropped
), service_indexes AS (
 SELECT jsonb_agg(jsonb_build_object('relation',i.indrelid::regclass::text,'name',c.relname,'unique',i.indisunique,
  'primary',i.indisprimary,'valid',i.indisvalid,'ready',i.indisready,
  'definition_sha256',encode(sha256(convert_to(pg_get_indexdef(i.indexrelid),'UTF8')),'hex')) ORDER BY c.relname COLLATE "C") value
 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
 WHERE i.indrelid=to_regclass('public.services') AND c.relname='services_public_discovery_idx'
), service_browser_privileges AS (
 SELECT jsonb_agg(jsonb_build_object('relation',relation,'role',role,
  'select',has_table_privilege(role,to_regclass(relation),'SELECT'),
  'insert',has_table_privilege(role,to_regclass(relation),'INSERT'),
  'update',has_table_privilege(role,to_regclass(relation),'UPDATE'),
  'delete',has_table_privilege(role,to_regclass(relation),'DELETE')) ORDER BY relation COLLATE "C",role COLLATE "C") value
 FROM unnest(ARRAY['public.services','public.service_images']) relation
 CROSS JOIN unnest(ARRAY['anon','authenticated']) role
), base AS (
 SELECT jsonb_build_object(
  'accepted_profile_marketplace_base',jsonb_set(prior_profile.b,'{dependencies}',
   (SELECT coalesce(jsonb_agg(x ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(prior_profile.b->'dependencies') WITH ORDINALITY v(x,ord)
    WHERE x->>'name'<>'service_publication_private.visible_to_viewer')),
  'accepted_profile_marketplace_readers',prior_profile.t,
  'dependencies',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM service_functions,jsonb_array_elements(value) x WHERE x->>'name' IN ('service_publication_private.public_fields','public.get_public_service_v1','public.search_public_services_v1')),
  'columns',(SELECT value FROM service_columns),'indexes',(SELECT value FROM service_indexes),
  'browser_privileges',(SELECT value FROM service_browser_privileges)) value FROM prior_profile
), target AS (
 SELECT jsonb_build_object('functions',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM service_functions,jsonb_array_elements(value) x WHERE x->>'name' IN ('service_publication_private.visible_to_viewer','public.get_public_profile_services_v1','public.get_public_profile_services_v2'))) value
)
SELECT base.value b,target.value t FROM base CROSS JOIN target
), job_functions AS MATERIALIZED (
 SELECT p.oid::regprocedure::text signature,jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),
 'language',l.lanname,'definer',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,
 'leakproof',p.proleakproof,'parallel',p.proparallel,'result',pg_get_function_result(p.oid),
 'arguments',p.proargnames,'defaults',pg_get_expr(p.proargdefaults,0),'config',p.proconfig,
 'body',encode(sha256(convert_to((p.prosrc)::text,'UTF8')),'hex'),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
 'privilege',x.privilege_type,'grantable',x.is_grantable)
 ORDER BY pg_get_userbyid(x.grantor) COLLATE "C",(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END) COLLATE "C",x.privilege_type COLLATE "C"),'[]'::jsonb)
 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x)) facts
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname||'.'||p.proname IN ('jobs_private.contact_snapshot','jobs_private.content','jobs_private.cursor','jobs_private.is_public','jobs_private.owner_fields','jobs_private.public_fields','jobs_private.require_actor','jobs_private.search_document','jobs_private.visible_to_viewer','public.contact_my_job_provider_v1','public.get_job_categories_v1','public.get_my_jobs_v1','public.get_public_job_v1','public.get_public_profile_jobs_v1','public.search_public_jobs_v1')
 ORDER BY n.nspname COLLATE "C",p.proname COLLATE "C",p.oid LIMIT 16) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
), job_relations AS MATERIALIZED (
 SELECT n.nspname||'.'||c.relname name,jsonb_build_object('name',n.nspname||'.'||c.relname,'kind',c.relkind,
 'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('position',a.attnum,'name',a.attname,
 'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,
 'default',pg_get_expr(d.adbin,d.adrelid),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
 'privilege',x.privilege_type,'grantable',x.is_grantable)
 ORDER BY pg_get_userbyid(x.grantor) COLLATE "C",(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END) COLLATE "C",x.privilege_type COLLATE "C"),'[]'::jsonb)
 FROM aclexplode(a.attacl) x)) ORDER BY a.attnum),'[]'::jsonb)
 FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.conname,'type',q.contype,
 'definition',pg_get_constraintdef(q.oid),'validated',q.convalidated) ORDER BY q.conname COLLATE "C"),'[]'::jsonb)
 FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype<>'n'),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',i.indexrelid::regclass::text,
 'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique)
 ORDER BY (i.indexrelid::regclass::text) COLLATE "C"),'[]'::jsonb) FROM pg_index i WHERE i.indrelid=c.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,
 'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname COLLATE "C"),'[]'::jsonb)
 FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
 'privilege',x.privilege_type,'grantable',x.is_grantable)
 ORDER BY pg_get_userbyid(x.grantor) COLLATE "C",(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END) COLLATE "C",x.privilege_type COLLATE "C"),'[]'::jsonb)
 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,
 'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END
 ORDER BY (CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) COLLATE "C") FROM unnest(p.polroles) r),
 'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))
 ORDER BY p.polname COLLATE "C"),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid=c.oid)) facts
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname||'.'||c.relname IN ('jobs_private.categories','public.jobs')
), job_schema AS (
